<template>
  <div class="demo-page">
    <header>
      <p class="demo-page__eyebrow">远程组件</p>
      <h1 class="demo-page__title">comps-vue3 · BookFlip</h1>
      <p class="demo-page__lead">
        来自 video-code 的「书本翻页」：一叠对开页贴在书脊右侧，绕左边缘 <code>rotateY(-180deg)</code>
        翻过去，正面转走背面转来，每面都有标题、正文和底图。原 demo 用 <code>z-index</code> +
        <code>visibility</code> 关键帧处理正反面切换；组件里改用 <code>backface-visibility: hidden</code>，
        逻辑简单很多，另外补了上一页 / 下一页、页码、键盘左右键和自动播放。
      </p>
    </header>

    <section class="book-demo">
      <div class="book-demo__head">
        <h2 class="demo-page__section-title">点右半页翻过去</h2>
        <code class="book-demo__tag">{{ page }} / {{ leaves }}</code>
      </div>
      <p class="demo-card__text">
        下面这本是 4 张内页（8 个面）加首尾封面：点右半页向前翻，点左边已经翻过的页可以翻回来；
        底部按钮和 ← → 键也能翻。底图是用内联 SVG 生成的渐变，不依赖外网。
      </p>

      <div class="book-demo__stage">
        <BookFlip
          v-model="page"
          :pages="pages"
          :cover="cover"
          :end-cover="endCover"
          :width="620"
          :height="400"
          :duration="1000"
          @change="onChange"
        />
      </div>

      <p class="book-demo__hint">
        当前第 <code>{{ page }}</code> 张（共 <code>{{ leaves }}</code> 张）· 最近一次翻页：
        <code>{{ lastChange }}</code>
      </p>

      <div class="book-demo__row">
        <div class="book-demo__cell">
          <div class="book-demo__stage book-demo__stage--small">
            <BookFlip
              :pages="pages.slice(0, 2)"
              :cover="cover"
              :end-cover="endCover"
              :width="360"
              :height="240"
              :duration="700"
              :hint="false"
              paper="#f3ecdc"
            />
          </div>
          <p>小尺寸 + 米色纸（<code>width</code> / <code>height</code> / <code>paper</code>）</p>
        </div>
        <div class="book-demo__cell">
          <div class="book-demo__stage book-demo__stage--small">
            <BookFlip
              :pages="pages.slice(0, 3)"
              :cover="cover"
              :end-cover="endCover"
              :width="360"
              :height="240"
              :duration="800"
              :autoplay="true"
              :autoplay-interval="1800"
              :controls="false"
              :hint="false"
            />
          </div>
          <p>自动播放（<code>autoplay</code>，翻到最后一页停下，无按钮）</p>
        </div>
      </div>
    </section>

    <DemoPreview class="book-preview">
      <LevaPlayground
        name="BookFlip"
        :component="BookFlip"
        :schema="BookFlipSchema"
        :presets="{ pages, cover, endCover, width: 560, height: 380 }"
        :stage-style="stageStyle"
      />
    </DemoPreview>

    <p class="demo-note">
      <span>
        面板里 <code>width</code> / <code>height</code> 是书页尺寸，<code>duration</code> 是一次翻页的毫秒数，
        <code>paper</code> / <code>ink</code> 是纸色和正文颜色，<code>modelValue</code> 是当前翻到第几张
        （和 <code>v-model</code> 同步），<code>controls</code> / <code>hint</code> 控制按钮和提示，
        <code>autoplay</code> + <code>autoplayInterval</code> 是自动翻页。内页数组用
        <code>pages</code> 传入（每张有 front / back 两面）。
      </span>
    </p>
  </div>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue'
import BookFlipSchema from '@melt-js/comps-vue3/src/components/BookFlip.propsSchema.json'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import { remoteComponent } from '../configs/remote'

const BookFlip = remoteComponent('BookFlip')

type Face = { title?: string; text?: string; image?: string }
type Page = { front: Face; back: Face }

const PALETTE = [
  ['#f97316', '#ec4899'],
  ['#22d3ee', '#3b82f6'],
  ['#a855f7', '#6366f1'],
  ['#34d399', '#14b8a6'],
  ['#fbbf24', '#f97316'],
  ['#f472b6', '#a855f7'],
  ['#38bdf8', '#818cf8'],
  ['#4ade80', '#22d3ee'],
]

/** 生成一张带编号的渐变底图，免得 demo 依赖外网图片 */
function poster(index: number): string {
  const [from, to] = PALETTE[index % PALETTE.length]
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="300" height="400">
    <defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="${from}"/><stop offset="1" stop-color="${to}"/>
    </linearGradient></defs>
    <rect width="300" height="400" fill="url(#g)"/>
    <text x="150" y="222" font-family="sans-serif" font-size="120" font-weight="700"
      fill="rgba(255,255,255,0.82)" text-anchor="middle">${index}</text>
  </svg>`
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`
}

const TEXTS = [
  '第一页：组件从一整页 demo 里被拆出来，带上自己的 props、事件和样式，能独立站在任何一个 Vue 3 项目里。',
  '第二页：所有视觉常量都变成了 props —— 尺寸、颜色、时长、开关，在属性面板里拖一拖就能看到差别。',
  '第三页：交互逻辑重新组织过：拖动、点击、缩放这些手势用 Pointer Events 统一处理，鼠标和触摸是同一套。',
  '第四页：动画尽量交给 CSS 和 rAF，Vue 只负责状态；每帧只写必要的 DOM，避免把响应式拖进动画循环里。',
]

const pages: Page[] = TEXTS.map((text, index) => ({
  front: {
    title: `第 ${index * 2 + 1} 面`,
    text,
    image: poster(index * 2 + 1),
  },
  back: {
    title: `第 ${index * 2 + 2} 面`,
    text: TEXTS[(index + 1) % TEXTS.length],
    image: poster(index * 2 + 2),
  },
}))

const cover: Face = { title: '『组件提取笔记』', text: '', image: poster(0) }
const endCover: Face = { title: '', text: '', image: poster(7) }

const page = ref(0)
const leaves = computed(() => pages.length + 2)
const lastChange = ref('（还没翻过）')

const stageStyle = {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  height: '560px',
  padding: '24px',
  background: '#4f4e68',
}

function onChange(value: number) {
  lastChange.value = `翻到第 ${value} 张`
}
</script>

